package com.distributedexam.server.dashboard;
import com.distributedexam.common.*; import com.distributedexam.dao.*; import com.distributedexam.remote.DashboardRemote; import java.rmi.*; import java.rmi.server.UnicastRemoteObject; import java.util.*;
public class DashboardManager extends UnicastRemoteObject implements DashboardRemote {
 private final RoomDAO rooms=new RoomDAOImpl(); private final ExamDAO exams=new ExamDAOImpl(); private final AttendanceDAO attendance=new AttendanceDAOImpl(); private final SubmissionDAO submissions=new SubmissionDAOImpl(); private final IncidentDAO incidents=new IncidentDAOImpl(); private final EventDAO events=new EventDAOImpl();
 public DashboardManager()throws RemoteException{} public DashboardSnapshot getCoordinatorSnapshot()throws Exception{return snapshot(null);} public DashboardSnapshot getRoomSnapshot(int id)throws Exception{return snapshot(id);}
 private DashboardSnapshot snapshot(Integer target)throws Exception{DashboardSnapshot d=new DashboardSnapshot();List<Room> rs=rooms.getAllRooms();if(target!=null)rs.removeIf(r->r.getRoomId()!=target);d.rooms.addAll(rs);d.totalRooms=rs.size();for(Room r:rs){d.roomStatusSummary.merge(r.getStatus().name(),1,Integer::sum);if(r.getStatus()==RoomStatus.OFFLINE)d.offlineRooms++;else d.onlineRooms++;if(r.getCurrentExamId()!=null){Exam e=exams.getExam(r.getCurrentExamId());if(e!=null&&e.getStatus()==ExamStatus.RUNNING)d.runningExams++;List<Attendance>a=attendance.getAttendanceByRoom(r.getCurrentExamId(),r.getRoomId());List<Submission>s=submissions.getSubmissionsByRoom(r.getCurrentExamId(),r.getRoomId());d.attendanceCount+=a.size();d.submissionCount+=s.size();int n=new ExamStudentDAOImpl().getStudentsInRoomForExam(r.getCurrentExamId(),r.getRoomId()).size();d.attendancePercentByRoom.put(r.getRoomId(),pct(a.stream().filter(x->"PRESENT".equalsIgnoreCase(x.getStatus())).count(),n));d.submissionProgressByRoom.put(r.getRoomId(),pct(s.stream().filter(x->"SUBMITTED".equalsIgnoreCase(x.getStatus())||"LATE".equalsIgnoreCase(x.getStatus())).count(),n));}}for(Exam e:exams.getAllExams())d.examCompletionStatus.put(e.getExamId(),e.getStatus().name());List<Incident> open=incidents.findOpen();if(target!=null)open.removeIf(i->!target.equals(i.getRoomId()));d.openIncidents=open.size();for(Incident i:open)d.incidentSummary.merge(i.getType(),1,Integer::sum);d.recentEvents=target==null?events.findRecent(20):events.findByRoom(target);return d;} private double pct(long a,long b){return b==0?0:Math.round(a*10000d/b)/100d;}
}
